// Test fixture dependency #2 (issue #89). Deliberately minimal and deliberately UNGRANTED: the
// tests that use it give it nothing in the policy, so every read below must be denied and
// recorded no matter what any OTHER package happens to be doing at the time.
//
// It exists because #89's worst property was not that the spawning package could read env — it
// is that the env gate was suspended PROCESS-WIDE, so a package with no grants at all read
// ungated for as long as someone else was inside a spawn. Proving that requires a second
// principal; fixture-dep cannot play both parts.
exports.read = (key) => process.env[key];

// The descriptor path too — the `get` trap's sibling hole (see shims/env.ts).
exports.readDescriptor = (key) => Object.getOwnPropertyDescriptor(process.env, key);

// Whole-environment harvest, the shape a real exfiltration payload uses.
exports.readAll = () => ({ ...process.env });

// ─────────────────────────────────────────────────────────────────────────────────────────────
// #90 — the composition matrix needs this package to hold NO grant of ANY kind, so that "does
// package A's privileged window open something for package B?" can be asked of every subsystem
// rather than only of `process.env`. Each helper below is one ungranted capability call; every
// one of them must be denied identically whether or not some other package happens to be inside
// a spawn, inside an authorized dgram send, or inside anything else.
// ─────────────────────────────────────────────────────────────────────────────────────────────

exports.readFile = (target) => require("fs").readFileSync(target, "utf8");

exports.connect = (host, port) => {
  const net = require("net");
  const s = net.connect({ host, port });
  s.on("error", () => {});
  s.destroy();
  return "connected";
};

exports.udpSend = (host, port) => {
  const dgram = require("dgram");
  const s = dgram.createSocket("udp4");
  const close = () => {
    try {
      s.close();
    } catch {}
  };
  try {
    s.send(Buffer.from("x"), port, host, close);
    return "sent";
  } catch (e) {
    close();
    throw e;
  }
};

exports.spawn = () => require("child_process").spawnSync(process.execPath, ["-e", ""]).status;

exports.runVm = (code) => require("vm").runInNewContext(code);

// ─────────────────────────────────────────────────────────────────────────────────────────────
// #133 — reads whose STACK SHAPE is chosen by the (ungranted) reader.
//
// The env shim now starts its stack capture directly below the trap and materializes only a few
// CallSites, falling back to the full walk when that does not reach a qualifying frame. The
// frames between this package and the trap are the one thing an attacker controls about that,
// so each helper below reads the same key through a different arrangement of them. Every one of
// them must still be charged to `fixture-envpeek` and denied — see attribution-fast-path.test.ts.
// ─────────────────────────────────────────────────────────────────────────────────────────────

// Interposes a native (file-name-less) frame between this package and the trap, the shape every
// `Object.assign` / `Array.prototype.map` enumeration has.
exports.readThroughBuiltin = (key) => [key].map((k) => process.env[k])[0];

// Three stacked builtins, so the reader's own frame is as far from the trap as ordinary code
// can push it without leaving JavaScript.
exports.readThroughBuiltins = (key) =>
  [key].map((k) => [k].map((k2) => [k2].map((k3) => process.env[k3])[0])[0])[0];

// The reader's own frames, deep. Nearest-package attribution should not care how many there are.
exports.readAtDepth = function readAtDepth(depth, key) {
  if (depth <= 0) return process.env[key];
  return exports.readAtDepth(depth - 1, key);
};

// Reads from inside `eval`. Every eval frame is OPAQUE (#84), so a run of them is exactly the
// case where a short capture finds no frame it may believe and must fall back rather than guess.
exports.readThroughEvals = (key, depth) => {
  const inner = `(function () { return process.env[${JSON.stringify(key)}]; })()`;
  let src = inner;
  for (let i = 0; i < depth; i++) src = `eval(${JSON.stringify(src)})`;
  // eslint-disable-next-line no-eval
  return eval(src);
};

// Runs `fn` (typically ANOTHER package's whole-environment enumeration) and then reads, with
// nothing in between — the interleaving a per-enumeration principal cache would get wrong.
exports.readRightAfter = (fn, key) => {
  fn();
  return process.env[key];
};

// Same, one macrotask later: a cached principal that outlives the tick that produced it.
exports.readNextTick = (fn, key) =>
  new Promise((resolve) => {
    fn();
    setTimeout(() => resolve(process.env[key]), 0);
  });

// ── Attribution probes ───────────────────────────────────────────────────────────────────────
//
// These call a test-supplied probe from THIS package's frames, which is what makes the fast
// path and the full walk COMPARABLE. Both entry points answer "the nearest package frame below
// the capwall frames", so both must answer `fixture-envpeek` — but only if the frame directly
// below them belongs to this package. A probe invoked from the test file instead would put an
// `<app>` frame in between and the two entry points would be answering different questions.
// So the interposition has to live here, next to the frames it is interposing.

exports.callProbe = (probe, arg) => probe(arg);

// One native, file-name-less frame between this package and the probe.
exports.callProbeThroughBuiltin = (probe, arg) => [0].map(() => probe(arg))[0];

// Three of them.
exports.callProbeThroughBuiltins = (probe, arg) =>
  [0].map(() => [0].map(() => [0].map(() => probe(arg))[0])[0])[0];

// This package's own frames, deep. Nearest-package attribution must not care.
exports.callProbeAtDepth = function callProbeAtDepth(depth, probe, arg) {
  if (depth <= 0) return probe(arg);
  return exports.callProbeAtDepth(depth - 1, probe, arg);
};

// `depth` nested DIRECT evals. Direct eval keeps this scope, so `probe`/`arg` stay reachable
// while every frame between them and the probe is OPAQUE (#84) — the one prefix an attacker can
// make uninformative, and therefore the case a short capture must decline rather than guess on.
exports.callProbeThroughEvals = (probe, arg, depth) => {
  let src = "probe(arg)";
  for (let i = 0; i < depth; i++) src = `eval(${JSON.stringify(src)})`;
  // eslint-disable-next-line no-eval
  return eval(src);
};
